import ApiInputKey from "@/components/ApiInputKey";
import FileUploader, { isAudioFile } from "@/components/FileUploader";
import { useState } from "react";
import { Sparkles } from "lucide-react";
import { generateYouTubeContent } from "@/services/OpenRouterAudio";
import GeneratedOutput from "@/GeneratedOutput";

interface GeneratedResponse {
  images: string[];
  titles: string[];
}

const getInitialGeneratedResponse = () => ({
  images: [
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
  ],
  titles: [
    "What Caused That Loud Pop? Diagnosing Burst Noise in Audio",
    "Remove Audio Clicks & Pops Fast: Causes and Quick Fixes",
    "One Sharp Pop in Your Track? How to Find and Remove It",
  ],
});
export default function HeroSection() {
  const [apiKey, setApiKey] = useState("");
  const [file, setFile] = useState<File | null>(null);

  const [generatedContent, setGeneratedContent] = useState<GeneratedResponse>(
    getInitialGeneratedResponse(),
  );
  const [isGenerating, setIsGenerating] = useState(false);

  const validateFile = (file: File): string | null => {
    if (!isAudioFile(file)) {
      return "Please upload an audio file";
    }

    return null;
  };

  const generateContent = async () => {
    if (!file || !apiKey) {
      return;
    }
    setIsGenerating(true);
    setGeneratedContent(getInitialGeneratedResponse());
    try {
      await generateYouTubeContent(file, apiKey, (output) => {
        const formattedOutput: GeneratedResponse = { images: [], titles: [] };
        const message = output.choices[0].message;
        if (message.images) {
          formattedOutput["images"] = message.images.map(
            (image) => image.imageUrl.url,
          );
        }
        formattedOutput["titles"] =
          typeof message.content === "string"
            ? JSON.parse(message.content).titles
            : [];

        setGeneratedContent(formattedOutput);
      });
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };
  return (
    <div className="min-h-full bg-linear-to-br from-slate-50 to-slate-100 py-12 px-6">
      <div className="text-center mb-6">
        <h1 className="text-2xl md:text-3xl font-extrabold text-slate-900 mb-4 tracking-tight">
          Upload Your Audio File
        </h1>
        <p className="text-lg text-slate-600 max-w-2xl mx-auto">
          We&apos;ll generate thumbnail ideas, titles, and descriptions
          automatically
        </p>
      </div>

      <ApiInputKey onChangeApiKey={setApiKey} apiKey={apiKey} />

      <FileUploader
        accept="audio/mp3,audio/*"
        validateFile={validateFile}
        syncFile={setFile}
      />
      <br />
      <button
        disabled={!file || !apiKey || isGenerating}
        onClick={generateContent}
        className="group mt-6 relative inline-flex items-center gap-2 px-8 py-4 text-lg font-semibold text-white  bg-red-600 rounded-xl shadow-lg transition-all duration-300 hover:shadow-xl hover:shadow-red-500/50 hover:-translate-y-0.5 active:translate-y-0 active:shadow-md disabled:bg-gray-400 disabled:shadow-none disabled:cursor-not-allowed disabled:transform-none"
      >
        <Sparkles className="w-5 h-5 transition-transform duration-300 group-hover:rotate-12" />
        <span>Generate Content</span>
      </button>

      <GeneratedOutput data={generatedContent} />
    </div>
  );
}
